function repere( ll) {
  push();
  noStroke();
  translate(ll, 0, 0);
  fill(255, 0, 0);
  box(2*ll, 50, 50);
  translate(-ll, ll, 0);
  fill(0, 255, 0);
  box(50, 2*ll, 50);
  translate(0, -ll, ll);
  fill(0, 0, 255);
  box(50, 50, 2*ll);
  pop();
}



function Bande() {

  this.nbnoeud=32;
  this.nbdiv=80;
  this.huits=[];
  this.couleurs=[];
  this.remplir();
}

Bande.prototype.remplir=function() { 
  for (var ic=0; ic<this.nbdiv; ic++) {
    var tha=TWO_PI/(this.nbdiv-1)*ic;
    this.huits[ic]=[];
    this.couleurs[ic]=[];
    for (var i=0; i<this.nbnoeud; i++) {
      var psi=TWO_PI/(this.nbnoeud-1)*i;      
      this.huits[ic][i]=this.coorabs(psi+ic*0.4, tha);
    }
  }
  for (var ic=0; ic<this.nbdiv-1; ic++) {
    for (var i=0; i<this.nbnoeud-1; i++) {
      var u=p5.Vector.sub( this.huits[ic][i], this.huits[ic][i+1]);
      var v=p5.Vector.sub( this.huits[ic][i], this.huits[ic+1][i+1]); 
      if (u.mag()<0.0001 || v.mag()<0.0001 ) {
        this.couleurs[ic][i]=createVector(50, 50, 50);
      } else {
        u.normalize();
        v.normalize();
        var w=u.cross(v);
        this.couleurs[ic][i]=p5.Vector.mult(w, 255);
      }
    }
  }
}
Bande.prototype.dessin=function() {
  noStroke();
  for (var ic=0; ic<this.nbdiv-1; ic++) {
    for (var i=0; i<this.nbnoeud-1; i++) {
      beginShape(TRIANGLE_STRIP);
     fill(255*(i%2));
      vertex( this.huits[ic][i].x, this.huits[ic][i].y, this.huits[ic][i].z);//1
      vertex( this.huits[ic+1][i].x, this.huits[ic+1][i].y, this.huits[ic+1][i].z);//6
      vertex( this.huits[ic][i+1].x, this.huits[ic][i+1].y, this.huits[ic][i+1].z);//2
      vertex( this.huits[ic+1][i+1].x, this.huits[ic+1][i+1].y, this.huits[ic+1][i+1].z);//3
      endShape();
    }
  }
}
Bande.prototype.coorabs=function(ps, th) {
  var xa=plus*cos(th)*cos(ps)+rayon*cos(ps);
  var ya=plus*cos(th)*sin(ps)+rayon*sin(ps);
  var za=plus*sin(th);

  return createVector(xa, ya, za);
}




function Cam(){
this.eye=createVector(0,0,0);
this.but=createVector(0,0,0);
this.crayon=500;
this.cradian=random(TWO_PI);
this.eyeSpeed=5.0;
this.cRadianSpeed=PI/100;
}



Cam.prototype.update=function()
{
if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
 this.eye.x+=this.eyeSpeed*cos(this.cradian);
 this.eye.z+=this.eyeSpeed*sin(this.cradian);
}
}



Cam.prototype.setCamera=function()
{
this.but.z=this.eye.z+this.crayon*cos(this.cradian);
 this.but.y=this.eye.y;
 this.but.x=this.eye.x-this.crayon*sin(this.cradian);
 camera(this.eye.x,this.eye.y,this.eye.z, this.but.x, this.but.y, this.but.z, 0, 1, 0);
}
